import { playerRatings } from "./playerRatings"

async function fetchExternalSoccerwikiRating(name: string) {
  const base = process.env.SOCCERWIKI_API_URL

  if (!base) return null

  try {
    const res = await fetch(
      `${base.replace(/\/$/, "")}/rating?name=${encodeURIComponent(name)}`
    )

    if (!res.ok) return null

    const data = await res.json()
    if (typeof data?.rating === "number") return data.rating
  } catch (error) {
    console.warn("Soccerwiki proxy fetch failed for", name, error)
  }

  return null
}

export async function computeTeamTotals(players: any[]) {
  if (!players || players.length === 0) {
    return {
      total: 0,
      average: 70,
      players: [],
    }
  }

  let total = 0

  const breakdown = []

  for (const item of players) {
    const name = item.player?.name || item.name || "Unknown Player"

    // Priority: explicit soccerWikiRating on the player object -> external API -> local playerRatings -> fallback
    let rating: number | null = null

    if (typeof item.soccerWikiRating === "number") {
      rating = item.soccerWikiRating
    }

    if (rating === null) {
      // try external proxy (optional)
      // Note: this may be slow if many players; it's acceptable for small lineups.
      // The env var SOCCERWIKI_API_URL should point to a proxy that returns JSON { rating: number }
      // for a given player name.
      // Example: SOCCERWIKI_API_URL=https://my-soccerwiki-proxy.example
      // Request made: GET /rating?name=Player+Name
      // If not provided, this step is skipped.
      // We await here to keep results consistent.
      // If you prefer parallelism, this function can be adjusted.
      // eslint-disable-next-line no-await-in-loop
      const ext = await fetchExternalSoccerwikiRating(name)
      if (typeof ext === "number") rating = ext
    }

    if (rating === null) {
      rating = playerRatings[name] || (68 + (name.length % 10))
    }

    total += rating

    breakdown.push({ name, rating })
  }

  return {
    total,
    average: Math.round(total / players.length),
    players: breakdown,
  }
}

export async function computeCombinedLineupTotals(lineups: any[]) {
  // Expecting two lineups: one per team. Sum their totals.
  const results = await Promise.all(
    (lineups || []).map(async (lu: any) => {
      const players = lu.startXI || []
      const teamName = lu.team?.name || "Team"
      const t = await computeTeamTotals(players)
      return {
        team: teamName,
        total: t.total,
        average: t.average,
        players: t.players,
      }
    })
  )

  const combined = results.reduce((acc, cur) => acc + (cur.total || 0), 0)

  return {
    teams: results,
    combinedTotal: combined,
  }
}

