import { NextResponse } from "next/server"
import { playerRatings } from "@/lib/playerRatings"

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url)
    const name = searchParams.get("name")

    if (!name) {
      return NextResponse.json({ error: "Missing name" }, { status: 400 })
    }

    // Check local ratings first
    if (playerRatings[name]) {
      return NextResponse.json({ rating: playerRatings[name] })
    }

    // Try scraping Soccerwiki search results as a best-effort fallback.
    // This is intentionally simple; you may want to replace with a dedicated proxy or cache.
    const searchUrl = `https://soccerwiki.org/index.php?search=${encodeURIComponent(
      name
    )}`

    try {
      const res = await fetch(searchUrl, {
        headers: {
          "User-Agent": "Mozilla/5.0 (compatible; QuantEdgeBot/1.0)",
        },
        cache: "no-store",
      })

      const html = await res.text()

      // Try to extract a numeric rating from the page (e.g., 'Rating: 86' or 'Overall: 86')
      const m = html.match(/(?:Rating|Overall)[:\s]+(\d{1,3})/i)
      if (m) {
        const value = Number(m[1])
        if (!Number.isNaN(value)) {
          return NextResponse.json({ rating: value })
        }
      }
    } catch (e) {
      console.warn("Soccerwiki fetch failed for", name, e)
    }

    return NextResponse.json({ rating: null })
  } catch (error) {
    console.error(error)
    return NextResponse.json({ error: "Failed" }, { status: 500 })
  }
}

// Best-effort Flashscore lineup scraper fallback.
// Flashscore HTML structure may change; this helper tries a few heuristics.
export async function fetchFlashscoreLineups(
  homeName: string,
  awayName: string,
  date?: string
) {
  if (!homeName || !awayName) return []

  // Create a naive slug from team names
  const slugCandidates = []
  const normalize = (s: string) =>
    s
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")

  slugCandidates.push(`${normalize(homeName)}-${normalize(awayName)}`)
  slugCandidates.push(`${normalize(awayName)}-${normalize(homeName)}`)

  for (const slug of slugCandidates) {
    const urls = [
      `https://www.flashscore.com/match/${slug}/#match-lineups`,
      `https://www.flashscore.com/match/${slug}/`,
      `https://m.flashscore.com/match/${slug}/`,
    ]

    for (const url of urls) {
      try {
        const res = await fetch(url, {
          headers: { "User-Agent": "Mozilla/5.0 (compatible; QuantEdgeBot/1.0)" },
          cache: "no-store",
        })

        if (!res.ok) continue

        const html = await res.text()

        // Heuristic: look for player name lists in the HTML
        // Common Flashscore markup includes participant names inside elements; we'll extract capitalized name groups
        const nameRegex = /([A-Z][a-z]+\s[A-Z][a-z]+(?:\s[A-Z][a-z]+)?)/g
        const matches = Array.from(new Set((html.match(nameRegex) || []).slice(0, 40)))

        if (matches.length >= 10) {
          // Split first 11 to home, next 11 to away as a best-effort
          const homePlayers = matches.slice(0, 11).map((n) => ({ player: { name: n } }))
          const awayPlayers = matches.slice(11, 22).map((n) => ({ player: { name: n } }))

          return [
            { team: { name: homeName }, startXI: homePlayers },
            { team: { name: awayName }, startXI: awayPlayers },
          ]
        }
      } catch (e) {
        console.warn("Flashscore fetch failed for", url, e)
      }
    }
  }

  return []
}

const API_KEY = process.env.API_FOOTBALL_KEY

import { fetchFlashscoreLineups } from "./fetchFlashscore"

export async function fetchLineups(fixtureId: number, opts?: { home?: string; away?: string; date?: string }) {
  try {
    const res = await fetch(
      `https://v3.football.api-sports.io/fixtures/lineups?fixture=${fixtureId}`,
      {
        headers: {
          "x-apisports-key": API_KEY || "",
        },
        cache: "no-store",
      }
    )

    const data = await res.json()

    if (data.errors?.rateLimit) {
  console.log("LINEUP RATE LIMITED")
  return []
}

    console.log("Lineups API Response:", data)
    const resp = data.response || []

    if ((!resp || resp.length === 0) && opts?.home && opts?.away) {
      console.log("No lineups from API, trying Flashscore fallback")
      const fs = await fetchFlashscoreLineups(opts.home, opts.away, opts.date)
      if (fs && fs.length > 0) return fs
    }

    return resp
  } catch (error) {
    console.error("Lineups fetch error:", error)
    return []
  }
}

