import { NextResponse } from "next/server"
import Stripe from "stripe"

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "", {
  apiVersion: "2022-11-15",
})

export async function POST(req: Request) {
  try {
    const { priceId, successUrl, cancelUrl } = await req.json()

    if (!priceId) {
      return NextResponse.json({ error: "Missing priceId" }, { status: 400 })
    }

    const session = await stripe.checkout.sessions.create({
      mode: "subscription",
      payment_method_types: ["card"],
      line_items: [{ price: priceId, quantity: 1 }],
      success_url: successUrl || `${process.env.NEXT_PUBLIC_APP_URL}/account?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: cancelUrl || `${process.env.NEXT_PUBLIC_APP_URL}/pricing`,
    })

    return NextResponse.json({ url: session.url })
  } catch (error) {
    console.error("Create session error:", error)
    return NextResponse.json({ error: "Failed to create session" }, { status: 500 })
  }
}

import { NextResponse } from "next/server"
import Stripe from "stripe"
import { supabase } from "@/lib/supabaseClient"

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "", {
  apiVersion: "2022-11-15",
})

export async function POST(req: Request) {
  const sig = req.headers.get("stripe-signature")
  const body = await req.text()

  try {
    const event = stripe.webhooks.constructEvent(
      body,
      sig || "",
      process.env.STRIPE_WEBHOOK_SECRET || ""
    )

    // Handle relevant events: checkout.session.completed, customer.subscription.updated, invoice.payment_succeeded
    switch (event.type) {
      case "checkout.session.completed": {
        const session = event.data.object as any
        // Upsert customer + subscription mapping into Supabase (requires table setup)
        try {
          await supabase.from("customers").upsert({
            stripe_customer_id: session.customer,
            checkout_session_id: session.id,
            metadata: session.metadata || {},
          })
        } catch (e) {
          console.warn("Supabase upsert failed", e)
        }
        break
      }

      case "customer.subscription.updated":
      case "customer.subscription.deleted":
      case "invoice.payment_succeeded": {
        const sub = event.data.object as any
        // Sync subscription status to Supabase
        try {
          await supabase.from("subscriptions").upsert({
            id: sub.id,
            customer: sub.customer,
            status: sub.status,
            price: sub.items?.data?.[0]?.price?.id || null,
            current_period_end: new Date((sub.current_period_end || 0) * 1000).toISOString(),
          })
        } catch (e) {
          console.warn("Supabase subscription sync failed", e)
        }
        break
      }
      default:
        break
    }

    return NextResponse.json({ received: true })
  } catch (err) {
    console.error("Stripe webhook error:", err)
    return NextResponse.json({ error: "Webhook processing failed" }, { status: 400 })
  }
}

import { NextResponse } from "next/server"
import type { NextRequest } from "next/server"
import { getAuth } from "@clerk/nextjs/server"
import { supabase } from "@/lib/supabaseClient"

const PROTECTED_PREFIXES = ["/app", "/account", "/api/secure"]

export async function middleware(req: NextRequest) {
  const { pathname } = req.nextUrl

  // Skip static and API public paths
  if (pathname.startsWith("/_next") || pathname.startsWith("/api/stripe/webhook")) {
    return NextResponse.next()
  }

  // If path is protected, ensure user is signed in and has an active subscription
  if (PROTECTED_PREFIXES.some((p) => pathname.startsWith(p))) {
    const { userId } = getAuth(req)
    if (!userId) {
      const signInUrl = new URL("/sign-in", req.url)
      return NextResponse.redirect(signInUrl)
    }

    try {
      const { data } = await supabase.from("subscriptions").select("*").eq("user_id", userId).limit(1)
      const sub = data?.[0]
      if (!sub || sub.status !== "active") {
        const pricingUrl = new URL("/pricing", req.url)
        return NextResponse.redirect(pricingUrl)
      }
    } catch (e) {
      console.warn("Subscription check failed", e)
    }
  }

  return NextResponse.next()
}

export const config = {
  matcher: ["/app/:path*", "/account/:path*", "/api/secure/:path*"],
}

